//! The doubly linked ring node and the arena that owns it.
//!
//! The C++ implementation threads raw `Node*` pointers through every routine
//! and keeps them alive in an object pool that is only released at the very
//! end. Removed nodes therefore stay readable, and code such as
//! `removeNode(p); removeNode(p->next);` relies on that. We reproduce the
//! model exactly with a `Vec<Node>` arena and `usize` handles: a handle is
//! never invalidated, so identity comparisons (`p != ear.prev`) and reads of
//! unlinked nodes behave as they do in C++.

use super::Earcut;

/// Handle standing in for a null `Node*`.
pub const NIL: usize = usize::MAX;

#[derive(Clone, Debug)]
pub struct Node {
    /// Index of this vertex in the flattened input coordinate list.
    pub i: u32,
    pub x: f64,
    pub y: f64,

    /// Previous and next vertex nodes in the polygon ring.
    pub prev: usize,
    pub next: usize,

    /// Z-order curve value.
    pub z: i32,

    /// Previous and next nodes in z-order.
    pub prev_z: usize,
    pub next_z: usize,

    /// Whether this is a Steiner point.
    pub steiner: bool,
}

impl Node {
