    pub(crate) fn y(&self, p: usize) -> f64 {
        self.nodes[p].y
    }

    #[inline]
    pub(crate) fn idx(&self, p: usize) -> u32 {
        self.nodes[p].i
    }

    #[inline]
    pub(crate) fn next(&self, p: usize) -> usize {
        self.nodes[p].next
    }

    #[inline]
    pub(crate) fn prev(&self, p: usize) -> usize {
