    pub(crate) fn insert_node(&mut self, i: usize, pt: [f64; 2], last: usize) -> usize {
        let p = self.construct(i as u32, pt[0], pt[1]);

        if last == NIL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
