    ///
    /// As in C++, `p`'s own `next`/`prev` fields are deliberately left intact.
    pub(crate) fn remove_node(&mut self, p: usize) {
        let (pn, pp) = (self.nodes[p].next, self.nodes[p].prev);
        self.nodes[pn].prev = pp;
        self.nodes[pp].next = pn;

        let (pz, nz) = (self.nodes[p].prev_z, self.nodes[p].next_z);
        if pz != NIL {
            self.nodes[pz].next_z = nz;
        }
        if nz != NIL {
            self.nodes[nz].prev_z = pz;
        }
    }

