    /// the ring into two. Returns the second ring's entry node (`b2`).
    pub(crate) fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self.construct(self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let b2 = self.construct(self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    /// `filterPoints(start, end)` — drop colinear or duplicate points.
    ///
    /// Pass [`NIL`] for `end` to get the C++ default argument (`end = start`).
    pub(crate) fn filter_points(&mut self, start: usize, end: usize) -> usize {
        if start == NIL {
            return NIL;
        }
        let mut end = if end == NIL { start } else { end };

        let mut p = start;
        loop {
            let mut again = false;

            let pn = self.nodes[p].next;
            let pp = self.nodes[p].prev;
            if !self.nodes[p].steiner && (self.equals(p, pn) || self.area(pp, p, pn) == 0.0) {
                self.remove_node(p);
                p = pp;
                end = pp;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = pn;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    /// `linkedList(points, clockwise)` — build a circular doubly linked list
    /// from one ring, in the requested winding order.
    pub(crate) fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
        let len = points.len();
        let mut last = NIL;

        // Calculate the original winding order of the ring.
        let mut sum = 0.0f64;
        if len > 0 {
            let mut j = len - 1;
            for i in 0..len {
                let p1 = points[i];
                let p2 = points[j];
                sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
                j = i;
            }
        }

        // Link points in the specified winding order.
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = self.insert_node(self.vertices + i, points[i], last);
            }
        } else {
            for i in (0..len).rev() {
                last = self.insert_node(self.vertices + i, points[i], last);
            }
        }

        if last != NIL {
            let last_next = self.nodes[last].next;
            if self.equals(last, last_next) {
                self.remove_node(last);
                last = last_next;
            }
        }

        self.vertices += len;

        last
    }
}

