    pub y: f64,

    /// Previous and next vertex nodes in the polygon ring.
    pub prev: usize,
    pub next: usize,

    /// Z-order curve value.
    pub z: i32,

    /// Previous and next nodes in z-order.
    pub prev_z: usize,
    pub next_z: usize,

    /// Whether this is a Steiner point.
    pub steiner: bool,
