//! Geometric predicates.
//!
//! Every expression here is kept in the exact algebraic form the C++ uses.
//! Rearranging them (even into a mathematically equivalent shape) changes
//! floating point rounding and can flip a `>= 0` test on a degenerate input,
//! which in turn changes which ear is clipped and therefore the output order.

use super::Earcut;

/// `area(p, q, r)` — twice the signed area of the triangle, negative for a
/// counter-clockwise turn.
#[inline]
pub fn area_xy(px: f64, py: f64, qx: f64, qy: f64, rx: f64, ry: f64) -> f64 {
    (qy - py) * (rx - qx) - (qx - px) * (ry - qy)
}

/// `pointInTriangle(...)` — boundary counts as inside (all tests are `>= 0`).
#[inline]
#[allow(clippy::too_many_arguments)]
pub fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

/// `sign(val)` — `(0 < val) - (val < 0)`.
#[inline]
pub fn sign(val: f64) -> i32 {
    i32::from(0.0 < val) - i32::from(val < 0.0)
}

impl Earcut {
    #[inline]
    pub(crate) fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        area_xy(
            self.x(p),
            self.y(p),
            self.x(q),
            self.y(q),
            self.x(r),
            self.y(r),
        )
    }

    /// `equals(p1, p2)` — exact coordinate equality.
    #[inline]
    pub(crate) fn equals(&self, p1: usize, p2: usize) -> bool {
        self.x(p1) == self.x(p2) && self.y(p1) == self.y(p2)
    }

    /// `onSegment(p, q, r)` — `q` lies inside the bounding box of `pr`.
    #[inline]
    pub(crate) fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
        self.x(q) <= f64::max(self.x(p), self.x(r))
            && self.x(q) >= f64::min(self.x(p), self.x(r))
            && self.y(q) <= f64::max(self.y(p), self.y(r))
            && self.y(q) >= f64::min(self.y(p), self.y(r))
    }

    /// `intersects(p1, q1, p2, q2)` — do the two segments properly or
    /// colinearly intersect?
    pub(crate) fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = sign(self.area(p1, q1, p2));
        let o2 = sign(self.area(p1, q1, q2));
        let o3 = sign(self.area(p2, q2, p1));
        let o4 = sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true; // general case
        }

        if o1 == 0 && self.on_segment(p1, p2, q1) {
            return true; // p1, q1 and p2 are colinear and p2 lies on p1q1
        }
        if o2 == 0 && self.on_segment(p1, q2, q1) {
            return true; // p1, q1 and q2 are colinear and q2 lies on p1q1
        }
        if o3 == 0 && self.on_segment(p2, p1, q2) {
            return true; // p2, q2 and p1 are colinear and p1 lies on p2q2
        }
        if o4 == 0 && self.on_segment(p2, q1, q2) {
            return true; // p2, q2 and q1 are colinear and q1 lies on p2q2
        }

        false
    }

    /// `intersectsPolygon(a, b)` — does the diagonal `ab` cross any ring edge?
    pub(crate) fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.next(p);
            if self.idx(p) != self.idx(a)
                && self.idx(pn) != self.idx(a)
                && self.idx(p) != self.idx(b)
                && self.idx(pn) != self.idx(b)
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }

        false
    }

    /// `locallyInside(a, b)` — is the segment `ab` inside the polygon in the
    /// immediate neighbourhood of `a`?
    pub(crate) fn locally_inside(&self, a: usize, b: usize) -> bool {
        let ap = self.prev(a);
        let an = self.next(a);
        if self.area(ap, a, an) < 0.0 {
            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
        } else {
            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
        }
    }

    /// `middleInside(a, b)` — is the midpoint of `ab` inside the polygon?
    pub(crate) fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.x(a) + self.x(b)) / 2.0;
        let py = (self.y(a) + self.y(b)) / 2.0;
        loop {
            let pn = self.next(p);
            if ((self.y(p) > py) != (self.y(pn) > py))
                && self.y(pn) != self.y(p)
                && (px
                    < (self.x(pn) - self.x(p)) * (py - self.y(p)) / (self.y(pn) - self.y(p))
                        + self.x(p))
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }

        inside
    }

    /// `isValidDiagonal(a, b)` — can the polygon be split along `ab`?
    pub(crate) fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let an = self.next(a);
        let ap = self.prev(a);
        let bp = self.prev(b);
        let bn = self.next(b);

        self.idx(an) != self.idx(b)
            && self.idx(ap) != self.idx(b)
            && !self.intersects_polygon(a, b) // doesn't intersect other edges
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)   // locally visible
                // does not create opposite-facing sectors
                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
                // special zero-length case
                || (self.equals(a, b)
                    && self.area(ap, a, an) > 0.0
                    && self.area(bp, b, bn) > 0.0))
    }

    /// `sectorContainsSector(m, p)` — whether the sector at `m` contains the
    /// sector at `p`.
    pub(crate) fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        self.area(self.prev(m), m, self.prev(p)) < 0.0
            && self.area(self.next(p), m, self.next(m)) < 0.0
    }
}

