    pub(crate) fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.next(p);
            if self.idx(p) != self.idx(a)
                && self.idx(pn) != self.idx(a)
                && self.idx(p) != self.idx(b)
                && self.idx(pn) != self.idx(b)
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }

        false
    }

    /// `locallyInside(a, b)` — is the segment `ab` inside the polygon in the
    /// immediate neighbourhood of `a`?
    pub(crate) fn locally_inside(&self, a: usize, b: usize) -> bool {
        let ap = self.prev(a);
        let an = self.next(a);
        if self.area(ap, a, an) < 0.0 {
            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
        } else {
            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
        }
    }

    /// `middleInside(a, b)` — is the midpoint of `ab` inside the polygon?
    pub(crate) fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.x(a) + self.x(b)) / 2.0;
        let py = (self.y(a) + self.y(b)) / 2.0;
        loop {
            let pn = self.next(p);
            if ((self.y(p) > py) != (self.y(pn) > py))
                && self.y(pn) != self.y(p)
                && (px
                    < (self.x(pn) - self.x(p)) * (py - self.y(p)) / (self.y(pn) - self.y(p))
                        + self.x(p))
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }

        inside
    }

    /// `isValidDiagonal(a, b)` — can the polygon be split along `ab`?
    pub(crate) fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let an = self.next(a);
        let ap = self.prev(a);
        let bp = self.prev(b);
        let bn = self.next(b);

        self.idx(an) != self.idx(b)
            && self.idx(ap) != self.idx(b)
            && !self.intersects_polygon(a, b) // doesn't intersect other edges
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)   // locally visible
                // does not create opposite-facing sectors
                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
                // special zero-length case
                || (self.equals(a, b)
                    && self.area(ap, a, an) > 0.0
                    && self.area(bp, b, bn) > 0.0))
    }

    /// `sectorContainsSector(m, p)` — whether the sector at `m` contains the
    /// sector at `p`.
    pub(crate) fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        self.area(self.prev(m), m, self.prev(p)) < 0.0
            && self.area(self.next(p), m, self.next(m)) < 0.0
    }
}

