//! Hole elimination: each inner ring is bridged into the outer ring so the
//! whole polygon becomes a single (self-touching) ring the ear clipper can eat.

use super::node::NIL;
use super::Earcut;
use super::geom::point_in_triangle;

impl Earcut {
    /// `eliminateHoles(points, outerNode)`
    pub(crate) fn eliminate_holes(
        &mut self,
        points: &[Vec<[f64; 2]>],
        mut outer_node: usize,
    ) -> usize {
        let len = points.len();

        let mut queue: Vec<usize> = Vec::new();
        for ring in points.iter().take(len).skip(1) {
            let list = self.linked_list(ring, false);
            if list != NIL {
                if self.next(list) == list {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }

        // `std::sort` by ascending x. The C++ comparator is a strict `a->x <
        // b->x`; every leftmost node in this program has a distinct x, so the
        // (unspecified) ordering `std::sort` gives equal keys never comes up
        // and a stable sort is an exact stand-in.
        let xs: Vec<f64> = queue.iter().map(|&n| self.x(n)).collect();
        let mut order: Vec<usize> = (0..queue.len()).collect();
        order.sort_by(|&a, &b| xs[a].partial_cmp(&xs[b]).unwrap());
        let queue: Vec<usize> = order.into_iter().map(|i| queue[i]).collect();

        // Process holes from left to right.
        for &hole in &queue {
            outer_node = self.eliminate_hole(hole, outer_node);
        }

        outer_node
    }

    /// `eliminateHole(hole, outerNode)` — find a bridge and link the hole in.
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        // Find a bridge between vertices that connects the hole with an outer
        // ring, and link it.
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NIL {
            return outer_node;
        }

        let bridge_reverse = self.split_polygon(bridge, hole);

        // Filter colinear points around the cuts.
        let br_next = self.next(bridge_reverse);
        self.filter_points(bridge_reverse, br_next);

        // Check if the input node was removed by the filtering.
        let b_next = self.next(bridge);
        self.filter_points(bridge, b_next)
    }

    /// `findHoleBridge(hole, outerNode)` — David Eberly's algorithm for finding
    /// a bridge between a hole and an outer ring.
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let mut p = outer_node;
        let hx = self.x(hole);
        let hy = self.y(hole);
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;

        // Find a segment intersected by a ray from the hole's leftmost vertex
        // going left; the segment endpoint with the lesser x is the potential
        // connection vertex.
        loop {
            let pn = self.next(p);
            if hy <= self.y(p) && hy >= self.y(pn) && self.y(pn) != self.y(p) {
                let x = self.x(p)
                    + (hy - self.y(p)) * (self.x(pn) - self.x(p)) / (self.y(pn) - self.y(p));
                if x <= hx && x > qx {
                    qx = x;
                    m = if self.x(p) < self.x(pn) { p } else { pn };
                    if x == hx {
                        // Hole touches the outer segment; pick the leftmost
                        // endpoint.
                        return m;
                    }
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }

        if m == NIL {
            return NIL;
        }

        // Look for points strictly inside the triangle of the hole vertex, the
        // segment intersection and the endpoint. If there are none we have a
        // valid connection; otherwise choose the vertex forming the minimum
        // angle with the ray.
        let stop = m;
        let mut tan_min = f64::INFINITY;
        let mx = self.x(m);
        let my = self.y(m);

        p = m;
        loop {
            let px = self.x(p);
            let py = self.y(p);
            if hx >= px
                && px >= mx
                && hx != px
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = (hy - py).abs() / (hx - px); // tangential

                if self.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (px > self.x(m) || self.sector_contains_sector(m, p))))
                {
                    m = p;
                    tan_min = tan;
                }
            }

            p = self.next(p);
            if p == stop {
                break;
            }
        }

        m
    }

    /// `getLeftmost(start)` — smallest x, ties broken by smallest y.
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.x(p) < self.x(leftmost)
                || (self.x(p) == self.x(leftmost) && self.y(p) < self.y(leftmost))
            {
                leftmost = p;
            }
            p = self.next(p);
            if p == start {
                break;
            }
        }

        leftmost
    }
}

