//! Z-order (Morton code) spatial hash.
//!
//! For polygons above a size threshold the ear test consults a z-order sorted
//! list instead of walking every remaining vertex. It is purely an
//! acceleration structure: the set of candidate points it visits is the same
//! set the linear scan would find inside the triangle, so both paths must
//! produce the same triangulation.

use super::geom::point_in_triangle;
use super::node::NIL;
use super::Earcut;

impl Earcut {
    /// `zOrder(x, y)` — interleave the bits of the two 15-bit coordinates.
    pub(crate) fn z_order(&self, x_: f64, y_: f64) -> i32 {
        // Coords are transformed into a non-negative 15-bit integer range.
        // The C++ `static_cast<int32_t>` truncates toward zero, which is what
        // Rust's `as` does for in-range values.
        let mut x = ((x_ - self.min_x) * self.inv_size) as i32;
        let mut y = ((y_ - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF_00FF;
        x = (x | (x << 4)) & 0x0F0F_0F0F;
        x = (x | (x << 2)) & 0x3333_3333;
        x = (x | (x << 1)) & 0x5555_5555;

        y = (y | (y << 8)) & 0x00FF_00FF;
        y = (y | (y << 4)) & 0x0F0F_0F0F;
        y = (y | (y << 2)) & 0x3333_3333;
        y = (y | (y << 1)) & 0x5555_5555;

        x | (y << 1)
    }

    /// `indexCurve(start)` — attach a z-order sorted linked list to the ring.
    pub(crate) fn index_curve(&mut self, start: usize) {
        debug_assert!(start != NIL);
        let mut p = start;

        loop {
            if self.nodes[p].z == 0 {
                self.nodes[p].z = self.z_order(self.x(p), self.y(p));
            }
            self.nodes[p].prev_z = self.nodes[p].prev;
            self.nodes[p].next_z = self.nodes[p].next;
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        // Break the circle so the merge sort sees a plain list.
        let pz = self.nodes[p].prev_z;
        self.nodes[pz].next_z = NIL;
        self.nodes[p].prev_z = NIL;

        self.sort_linked(p);
    }

    /// `sortLinked(list)` — bottom-up merge sort of the z-order linked list.
    ///
    /// The `p.z <= q.z` comparison makes the sort stable, so nodes with equal
    /// z keep their ring order. That ordering is observable in the output.
    pub(crate) fn sort_linked(&mut self, list: usize) -> usize {
        debug_assert!(list != NIL);
        let mut list = list;
        let mut in_size: i32 = 1;

        loop {
            let mut p = list;
            list = NIL;
            let mut tail = NIL;
            let mut num_merges = 0;

            while p != NIL {
                num_merges += 1;
                let mut q = p;
                let mut p_size: i32 = 0;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NIL {
                        break;
                    }
                }

                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NIL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NIL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NIL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }

                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            self.nodes[tail].next_z = NIL;

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }

    /// `isEarHashed(ear)` — the z-order accelerated ear test.
    pub(crate) fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.prev(ear);
        let b = ear;
        let c = self.next(ear);

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.x(a), self.y(a));
        let (bx, by) = (self.x(b), self.y(b));
        let (cx, cy) = (self.x(c), self.y(c));

        // Triangle bbox; min & max are calculated like this for speed.
        let min_tx = f64::min(ax, f64::min(bx, cx));
        let min_ty = f64::min(ay, f64::min(by, cy));
        let max_tx = f64::max(ax, f64::max(bx, cx));
        let max_ty = f64::max(ay, f64::max(by, cy));

        // Z-order range for the current triangle bbox.
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        let mut p = self.nodes[ear].prev_z;
        let mut n = self.nodes[ear].next_z;

        // Look for points inside the triangle in both directions.
        while p != NIL && self.nodes[p].z >= min_z && n != NIL && self.nodes[n].z <= max_z {
            if self.x(p) >= min_tx
                && self.x(p) <= max_tx
                && self.y(p) >= min_ty
                && self.y(p) <= max_ty
                && p != a
                && p != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(p), self.y(p))
                && self.area(self.prev(p), p, self.next(p)) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;

            if self.x(n) >= min_tx
                && self.x(n) <= max_tx
                && self.y(n) >= min_ty
                && self.y(n) <= max_ty
                && n != a
                && n != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(n), self.y(n))
                && self.area(self.prev(n), n, self.next(n)) >= 0.0
            {
                return false;
            }
            n = self.nodes[n].next_z;
        }

        // Look for remaining points in decreasing z-order.
        while p != NIL && self.nodes[p].z >= min_z {
            if p != a
                && p != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(p), self.y(p))
                && self.area(self.prev(p), p, self.next(p)) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;
        }

        // Look for remaining points in increasing z-order.
        while n != NIL && self.nodes[n].z <= max_z {
            if n != a
                && n != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(n), self.y(n))
                && self.area(self.prev(n), n, self.next(n)) >= 0.0
            {
                return false;
            }
            n = self.nodes[n].next_z;
        }

        true
    }
}

