//! A from-scratch Rust port of the `mapbox::earcut` polygon triangulator.
//!
//! Input is a polygon given as a list of rings: ring 0 is the outer contour and
//! every following ring is a hole. Vertex indices in the returned triangle list
//! refer to the flattened concatenation of all rings, so ring 1's first vertex
//! has index `ring0.len()`.
//!
//! The algorithm is ear clipping with three escalating fallbacks for input that
//! is not a simple polygon: filtering degenerate points, curing local
//! self-intersections, and finally splitting the ring along a valid diagonal.
//! Because that fallback ladder makes the output order depend on fine details
//! of the traversal, this port follows the reference control flow statement for
//! statement rather than reformulating it.

mod geom;
mod holes;
mod node;
mod zorder;

pub use geom::{area_xy, point_in_triangle, sign};
pub use node::{Node, NIL};

/// Triangulate a polygon, returning a flat list of triangle vertex indices.
///
/// Equivalent to `mapbox::earcut<uint32_t>(polygon)`.
pub fn earcut(polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let mut state = Earcut::new();
    state.run(polygon);
    state.indices
}

/// Triangulation state: the node arena plus the z-order hash parameters.
pub struct Earcut {
    /// Flat triangle list, three vertex indices per triangle.
    pub indices: Vec<u32>,
    /// Number of vertices consumed by rings linked so far.
    vertices: usize,
    /// Arena backing every [`Node`]; handles into it are never invalidated.
    nodes: Vec<Node>,

    hashing: bool,
    min_x: f64,
    max_x: f64,
    min_y: f64,
    max_y: f64,
    inv_size: f64,
}

impl Default for Earcut {
    fn default() -> Self {
        Self::new()
    }
}

impl Earcut {
    pub fn new() -> Self {
        Earcut {
            indices: Vec::new(),
            vertices: 0,
            nodes: Vec::new(),
            hashing: false,
            min_x: 0.0,
            max_x: 0.0,
            min_y: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    /// `operator()(points)` — the top level driver.
    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
        self.indices.clear();
        self.vertices = 0;

        if points.is_empty() {
            return;
        }

        // Decide whether the shape is complex enough to be worth hashing, and
        // size the arena while we are walking the rings. The loop stops early
        // once the threshold goes negative, so `len` is only a lower bound.
        let mut threshold: i32 = 80;
        let mut len: usize = 0;
        let mut i = 0;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i32;
            len += points[i].len();
            i += 1;
        }

        self.nodes.reserve(len * 3 / 2);
        self.indices.reserve(len + points[0].len());

        let mut outer_node = self.linked_list(&points[0], true);
        if outer_node == NIL || self.prev(outer_node) == self.next(outer_node) {
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // If the shape is not too simple we use a z-order curve hash later, so
        // calculate the polygon bbox now.
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.next(outer_node);
            self.min_x = self.x(outer_node);
            self.max_x = self.min_x;
            self.min_y = self.y(outer_node);
            self.max_y = self.min_y;
            loop {
                let (x, y) = (self.x(p), self.y(p));
                self.min_x = f64::min(self.min_x, x);
                self.min_y = f64::min(self.min_y, y);
                self.max_x = f64::max(self.max_x, x);
                self.max_y = f64::max(self.max_y, y);
                p = self.next(p);
                if p == outer_node {
                    break;
                }
            }

            // min_x, min_y and inv_size transform coords into the integer range
            // the z-order calculation wants.
            self.inv_size = f64::max(self.max_x - self.min_x, self.max_y - self.min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, 0);

        self.nodes.clear();
    }

    /// `earcutLinked(ear, pass)` — main ear slicing loop.
    fn earcut_linked(&mut self, ear: usize, pass: i32) {
        if ear == NIL {
            return;
        }
        let mut ear = ear;

        // Interlink polygon nodes in z-order.
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // Iterate through ears, slicing them one by one.
        while self.prev(ear) != self.next(ear) {
            let prev = self.prev(ear);
            let next = self.next(ear);

            let found = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if found {
                // Cut off the triangle.
                self.indices.push(self.idx(prev));
                self.indices.push(self.idx(ear));
                self.indices.push(self.idx(next));

                self.remove_node(ear);

                // Skipping the next vertex leads to fewer sliver triangles.
                ear = self.next(next);
                stop = self.next(next);

                continue;
            }

            ear = next;

            // If we looped through the whole remaining polygon and can't find
            // any more ears, escalate.
            if ear == stop {
                if pass == 0 {
                    // Try filtering points and slicing again.
                    let filtered = self.filter_points(ear, NIL);
                    self.earcut_linked(filtered, 1);
                } else if pass == 1 {
                    // If that didn't work, try curing all small
                    // self-intersections locally.
                    let filtered = self.filter_points(ear, NIL);
                    let cured = self.cure_local_intersections(filtered);
                    self.earcut_linked(cured, 2);
                } else if pass == 2 {
                    // As a last resort, try splitting the remaining polygon
                    // into two.
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    /// `isEar(ear)` — linear scan ear test used when hashing is off.
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.prev(ear);
        let b = ear;
        let c = self.next(ear);

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // Now make sure we don't have other points inside the potential ear.
        let mut p = self.next(self.next(ear));

        while p != self.prev(ear) {
            if point_in_triangle(
                self.x(a),
                self.y(a),
                self.x(b),
                self.y(b),
                self.x(c),
                self.y(c),
                self.x(p),
                self.y(p),
            ) && self.area(self.prev(p), p, self.next(p)) >= 0.0
            {
                return false;
            }
            p = self.next(p);
        }

        true
    }

    /// `cureLocalIntersections(start)` — go through all polygon nodes and cure
    /// small local self-intersections.
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        if start == NIL {
            return NIL;
        }
        let mut start = start;
        let mut p = start;

        loop {
            let a = self.prev(p);
            let pn = self.next(p);
            let b = self.next(pn);

            // A self-intersection where edge (v[i-1], v[i]) intersects
            // (v[i+1], v[i+2]).
            if !self.equals(a, b)
                && self.intersects(a, p, pn, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.idx(a));
                self.indices.push(self.idx(p));
                self.indices.push(self.idx(b));

                // Remove the two nodes involved. `remove_node` leaves `p`'s own
                // links intact, so `p.next` still names the second victim.
                self.remove_node(p);
                let p_next = self.next(p);
                self.remove_node(p_next);

                p = b;
                start = b;
            }

            p = self.next(p);
            if p == start {
                break;
            }
        }

        self.filter_points(p, NIL)
    }

    /// `splitEarcut(start)` — try splitting the polygon into two, then
    /// triangulate both halves independently.
    fn split_earcut(&mut self, start: usize) {
        // Look for a valid diagonal that divides the polygon in two.
        let mut a = start;
        loop {
            let mut b = self.next(self.next(a));
            while b != self.prev(a) {
                if self.idx(a) != self.idx(b) && self.is_valid_diagonal(a, b) {
                    // Split the polygon in two by the diagonal.
                    let mut c = self.split_polygon(a, b);

                    // Filter colinear points around the cuts.
                    let a_next = self.next(a);
                    let a = self.filter_points(a, a_next);
                    let c_next = self.next(c);
                    c = self.filter_points(c, c_next);

                    // Run earcut on each half.
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.next(b);
            }
            a = self.next(a);
            if a == start {
                break;
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::earcut;

    #[test]
    fn single_square() {
        let square = vec![vec![[0.0, 0.0], [1.0, 0.0], [1.0, 1.0], [0.0, 1.0]]];
        assert_eq!(earcut(&square), vec![2, 3, 0, 0, 1, 2]);
    }

    #[test]
    fn empty_polygon() {
        let empty: Vec<Vec<[f64; 2]>> = Vec::new();
        assert!(earcut(&empty).is_empty());
    }

    #[test]
    fn square_with_a_real_hole() {
        let polygon = vec![
            vec![[0.0, 0.0], [4.0, 0.0], [4.0, 4.0], [0.0, 4.0]],
            vec![[1.0, 1.0], [1.0, 3.0], [3.0, 3.0], [3.0, 1.0]],
        ];
        let indices = earcut(&polygon);
        // Eight vertices, one hole: 2 * 8 - 2 - 2 * 1 = 8 triangles.
        assert_eq!(indices.len(), 24);
        assert!(indices.iter().all(|&i| i < 8));
    }
}

