//! The polygon `test4.cpp` builds.
//!
//! `n` rings, each an axis-aligned square of side `n` whose lower-left corner
//! sits at `(2i, 2i)`. Because the offset step (2) is smaller than the side
//! (`n`) for all `n > 2`, the rings overlap heavily instead of nesting, so
//! earcut sees a badly self-intersecting polygon and exercises its fallback
//! paths. Ring 0 is treated as the outer contour and rings 1.. as holes.

/// Build the polygon for a given `n`. A non-positive `n` yields no rings,
/// exactly as the C++ `for (int i = 0; i < n; i++)` loop does.
pub fn overlapping_squares(n: i32) -> Vec<Vec<[f64; 2]>> {
    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();

    let side = f64::from(n);
    let mut i: i32 = 0;
    while i < n {
        // `double offset = i * 2;` — int multiply, then widen.
        let offset = f64::from(i.wrapping_mul(2));
        polygon.push(vec![
            [offset, offset],
            [offset + side, offset],
            [offset + side, offset + side],
            [offset, offset + side],
        ]);
        i += 1;
    }

    polygon
}

#[cfg(test)]
mod tests {
    use super::overlapping_squares;

    #[test]
    fn shape_matches_the_cpp_loop() {
        assert!(overlapping_squares(0).is_empty());
        assert!(overlapping_squares(-3).is_empty());

        let p = overlapping_squares(3);
        assert_eq!(p.len(), 3);
        assert!(p.iter().all(|ring| ring.len() == 4));
        assert_eq!(p[0], [[0.0, 0.0], [3.0, 0.0], [3.0, 3.0], [0.0, 3.0]]);
        assert_eq!(p[2], [[4.0, 4.0], [7.0, 4.0], [7.0, 7.0], [4.0, 7.0]]);
    }
}

